# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# IM5, OIM5 and IM7 instructions (VLEPEM Rev. 0 Figures A-3 to A-5).  OIM5
# encodes 1-32 as 0-31.

# CHECK: se_addi 3, 1 # encoding: [0x20,0x03]
se_addi 3, 1
# CHECK: se_addi 3, 32 # encoding: [0x21,0xf3]
se_addi 3, 32
# CHECK: se_cmpli 3, 1 # encoding: [0x22,0x03]
se_cmpli 3, 1
# CHECK: se_cmpli 3, 32 # encoding: [0x23,0xf3]
se_cmpli 3, 32
# CHECK: se_subi 3, 1 # encoding: [0x24,0x03]
se_subi 3, 1
# CHECK: se_subi 3, 32 # encoding: [0x25,0xf3]
se_subi 3, 32
# CHECK: se_subi. 3, 1 # encoding: [0x26,0x03]
se_subi. 3, 1
# CHECK: se_cmpi 3, 0 # encoding: [0x2a,0x03]
se_cmpi 3, 0
# CHECK: se_cmpi 3, 31 # encoding: [0x2b,0xf3]
se_cmpi 3, 31
# CHECK: se_bmaski 3, 0 # encoding: [0x2c,0x03]
se_bmaski 3, 0
# CHECK: se_bmaski 3, 31 # encoding: [0x2d,0xf3]
se_bmaski 3, 31
# CHECK: se_andi 3, 1 # encoding: [0x2e,0x13]
se_andi 3, 1
# CHECK: se_bclri 3, 1 # encoding: [0x60,0x13]
se_bclri 3, 1
# CHECK: se_bgeni 3, 1 # encoding: [0x62,0x13]
se_bgeni 3, 1
# CHECK: se_bseti 3, 1 # encoding: [0x64,0x13]
se_bseti 3, 1
# CHECK: se_btsti 3, 31 # encoding: [0x67,0xf3]
se_btsti 3, 31
# CHECK: se_srwi 3, 1 # encoding: [0x68,0x13]
se_srwi 3, 1
# CHECK: se_srawi 3, 1 # encoding: [0x6a,0x13]
se_srawi 3, 1
# CHECK: se_slwi 3, 1 # encoding: [0x6c,0x13]
se_slwi 3, 1
# CHECK: se_li 3, 0 # encoding: [0x48,0x03]
se_li 3, 0
# CHECK: se_li 3, 127 # encoding: [0x4f,0xf3]
se_li 3, 127
# CHECK: se_li 31, 1 # encoding: [0x48,0x1f]
se_li 31, 1
